//! 🚪️ Genuine declared Process3d public routes compile before optional SQLite capability wiring.
use super::*;
use store::io::{ArtifactDialect,io_mechanism::{io_route,io_run_with_snapshot_control}};
use store::io_schema::{IoPayload,IoFidelity,SQLITE_SNAPSHOT};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteDatabaseLimits,SqliteSnapshotPhase};
use std::{io::Write,process::{Command,Stdio}};
fn cohort()->serde_json::Value{serde_json::from_str(include_str!("../../../🧫️fixtures/🪶️sqlite/🚦️public/🔣️.json")).unwrap()}
fn dialect()->ArtifactDialect{let f=cohort();ArtifactDialect{artifact_kind:f["dialect"]["artifactKind"].as_str().unwrap().into(),standard:f["dialect"]["standard"].as_str().unwrap().into(),subset:f["dialect"]["subset"].as_str().unwrap().into()}}
fn publish(){semio_framework_plugin::Plugin::<SqliteProcessApps>::builder("process").label("Process3d actual public SQLite parent").version("0.0.1").package_id("semio:process").artifact(crate::declaration().unwrap()).try_build().unwrap();}
fn payload(value:&Process3dSnapshot,encoding:SnapshotEncoding)->IoPayload{match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(value.encode_pack_with(&store::PackEncodeOptions::default()).unwrap()),SnapshotEncoding::Text=>IoPayload::Text(value.print_dsl())}}
fn independent(word:u64,encoding:SnapshotEncoding)->Vec<u8>{let factory=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../🏅️standards/🔖️1/🪆️subsets/✳️any/🧬️schema/📸️snapshot/🧫️fixtures/🪶️sqlite/🟦️.ts").canonicalize().unwrap();let script="const{independentProcess3dSqliteFile}=await import(process.argv[1]);await Bun.write(Bun.stdout,await independentProcess3dSqliteFile(process.argv[2],process.argv[3],true));";let output=Command::new("bun").args(["-e",script,factory.to_str().unwrap(),&format!("{word:016x}"),encoding.as_str()]).output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));output.stdout}
fn inspect(bytes:&[u8],word:u64,encoding:SnapshotEncoding){let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});const c=JSON.parse(process.argv[1]),l=JSON.parse(process.argv[2]);if(d.query("SELECT name FROM sqlite_schema WHERE type='table'").all().length!==c.domainTables+c.metadataRows)throw Error('tables');if(d.query('SELECT stock_id FROM process3_document').get().stock_id!==l.rootStock.id)throw Error('root');if(d.query('SELECT native_id FROM process3_stock_payload').get().native_id!==l.payloadStock.id)throw Error('payload');if(d.query('SELECT native_encoding FROM semio_snapshot').get().native_encoding!==process.argv[4])throw Error('encoding');if(BigInt.asUintN(64,d.query('SELECT angle_ieee754_bits FROM process3_measure_pose LIMIT 1').get().angle_ieee754_bits).toString(16).padStart(16,'0')!==process.argv[3])throw Error('word');if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');d.close();"#;let mut child=Command::new("bun").args(["-e",script,&cohort().to_string(),&laws().to_string(),&format!("{word:016x}"),encoding.as_str()]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();let write=child.stdin.take().unwrap().write_all(bytes);let output=child.wait_with_output().unwrap();assert!(write.is_ok()&&output.status.success(),"Process3d independent oracle word={word:016x} encoding={} bytes={} write={write:?} status={} stdout={} stderr={}",encoding.as_str(),bytes.len(),output.status,String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));}

#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_process3d_public_declared_export_reaches_full_native_and_independent_physical_fields(){
 publish();let from=dialect();let into=ArtifactDialect::from(SQLITE_SNAPSHOT);let route=io_route(&from,&into,1).await.expect("actual declared Process3d parent must publish its SQLite export route").value;assert_eq!(route.hops.len(),cohort()["routeHops"].as_u64().unwrap()as usize);assert_eq!(route.fidelity,IoFidelity::Exact);
 for word in words(){let expected=full(word);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let input=payload(&expected,encoding);let mut phases=Vec::new();let file=io_run_with_snapshot_control(&route,input,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.expect("actual Process3d native owner must produce its physical SQLite file").value;let IoPayload::Binary(bytes)=file else{panic!("SQLite public endpoint must return binary")};inspect(&bytes,word,encoding);for phase in[SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::WritePages]{assert!(phases.contains(&phase),"missing actual public export phase {phase:?}");}}}
}

#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_process3d_public_declared_import_binds_independent_semantic_rows_and_exact_native_words(){
 publish();let from=ArtifactDialect::from(SQLITE_SNAPSHOT);let into=dialect();let route=io_route(&from,&into,1).await.expect("actual declared Process3d parent must publish its SQLite import route").value;assert_eq!(route.hops.len(),cohort()["routeHops"].as_u64().unwrap()as usize);assert_eq!(route.fidelity,IoFidelity::Exact);
 for word in words(){let mut expected=full(word);expected.stock_payload.label=cohort()["independentEdit"]["value"].as_str().unwrap().into();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let input=IoPayload::Binary(independent(word,encoding));let mut phases=Vec::new();let output=io_run_with_snapshot_control(&route,input,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.expect("independent semantic Process3d SQLite file must reach the actual native owner").value;assert_eq!(output,payload(&expected,encoding),"actual literal DSL/Pack output differs from the owner factory");let actual=match output{IoPayload::Binary(bytes)=>Process3dSnapshot::decode_pack(&bytes).unwrap(),IoPayload::Text(text)=>Process3dSnapshot::parse_dsl(&text).unwrap()};assert_full(&actual,&expected,word);for phase in[SqliteSnapshotPhase::ReadPages,SqliteSnapshotPhase::ReconstructSnapshot,SqliteSnapshotPhase::EncodeNative]{assert!(phases.contains(&phase),"missing actual public import phase {phase:?}");}}}
}
